CREATE TABLE organization_roots(id TEXT PRIMARY KEY,path BLOB NOT NULL,authority_json TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE organization_plans(id TEXT PRIMARY KEY,revision TEXT NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE organization_plan_rows(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES organization_plans(id) ON DELETE CASCADE,track_id TEXT NOT NULL REFERENCES tracks(id),ordinal INTEGER NOT NULL,outcome TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(plan_id,ordinal));
CREATE TABLE organization_owned_sidecars(track_id TEXT NOT NULL REFERENCES tracks(id),path BLOB NOT NULL,source_hash TEXT NOT NULL,manifest_id TEXT NOT NULL,ordinal INTEGER NOT NULL,PRIMARY KEY(track_id,path));
INSERT INTO organization_owned_sidecars SELECT w.track_id,f.target,f.after_hash,w.id,f.ordinal FROM tag_write_files f JOIN tag_writes w ON w.id=f.write_id WHERE f.ordinal>0 AND w.state='committed' AND w.id=(SELECT w2.id FROM tag_writes w2 WHERE w2.track_id=w.track_id AND w2.state='committed' ORDER BY w2.created DESC,w2.id DESC LIMIT 1);
CREATE TABLE organization_batches(id TEXT PRIMARY KEY,preview_id TEXT REFERENCES organization_plans(id),undo_of TEXT REFERENCES organization_batches(id),kind TEXT NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,cancel_requested INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE organization_batch_rows(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES organization_batches(id),track_id TEXT NOT NULL REFERENCES tracks(id),ordinal INTEGER NOT NULL,operation_id TEXT REFERENCES organization_operations(id),outcome TEXT NOT NULL,payload_json TEXT NOT NULL,error TEXT,UNIQUE(batch_id,ordinal));
CREATE INDEX organization_batch_track ON organization_batch_rows(track_id,batch_id);
CREATE TABLE preparation_checkpoints(job_id TEXT PRIMARY KEY REFERENCES jobs(id),track_id TEXT NOT NULL REFERENCES tracks(id),settings_revision TEXT NOT NULL REFERENCES settings(revision),input_hash TEXT NOT NULL,output_hash TEXT NOT NULL,attempt INTEGER NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL,batch_id TEXT REFERENCES organization_batches(id),created INTEGER NOT NULL,updated INTEGER NOT NULL);
ALTER TABLE tracks ADD COLUMN path_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE tracks ADD COLUMN metadata_revision INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER organization_path_revision AFTER UPDATE OF path ON tracks WHEN OLD.path IS NOT NEW.path BEGIN UPDATE tracks SET path_revision=path_revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER organization_metadata_revision AFTER UPDATE OF title,artist,album,genre,source_hash,native_metadata_json,metadata_json,analysis_json,musical_key,bpm,energy,duration ON tracks WHEN OLD.title IS NOT NEW.title OR OLD.artist IS NOT NEW.artist OR OLD.album IS NOT NEW.album OR OLD.genre IS NOT NEW.genre OR OLD.source_hash IS NOT NEW.source_hash OR OLD.native_metadata_json IS NOT NEW.native_metadata_json OR OLD.metadata_json IS NOT NEW.metadata_json OR OLD.analysis_json IS NOT NEW.analysis_json OR OLD.musical_key IS NOT NEW.musical_key OR OLD.bpm IS NOT NEW.bpm OR OLD.energy IS NOT NEW.energy OR OLD.duration IS NOT NEW.duration BEGIN UPDATE tracks SET metadata_revision=metadata_revision+1 WHERE id=NEW.id;END;
PRAGMA user_version=16;
